import { readFile } from 'node:fs/promises';
export const UI_STYLE_PARTS = [
  'controls',
  'forms',
  'motion',
  'conversion',
  'discovery',
  'editors',
  'workbench',
  'home',
  'startup',
  'preferences',
  'reference',
];
export async function uiStyleSource() {
  const parts = await Promise.all(
    UI_STYLE_PARTS.map((name) =>
      readFile(new URL('../public/ui/styles/' + name + '.css', import.meta.url), 'utf8'),
    ),
  );
  return (
    '/* Generated by npm run build:ui; edit public/ui/styles. Order preserves the shared cascade. */\n' +
    parts
      .map((text, index) => '/* --- ' + UI_STYLE_PARTS[index] + ' --- */\n' + text.trimEnd() + '\n')
      .join('\n')
  );
}
